def test_totals_does_not_modify_input():
    events = [
        {"tenant": "a", "id": "x", "seq": 1, "amount": 1},
        {"tenant": "a", "id": "x", "seq": 2, "amount": 2, "deleted": True},
        {"tenant": "b", "id": "y", "seq": 1, "amount": 3},
    ]
    snapshot = copy.deepcopy(events)
    order = list(events)
    totals(events)
    assert events == snapshot
    assert events == order


